import {validateRoomPolygon} from './room-geometry.js';
import {uid,wall} from './model.js';
import {likelyTreadRuns} from './plan-ink.js';
// Raster line evidence, not semantic recognition. All output requires review.
export function detectLines({data,width,height},crop={x:0,y:0,w:width,h:height},{minLength=35,threshold=135}={}){
 const black=(x,y)=>{const n=(y*width+x)*4;return data[n+3]>80&&(data[n]+data[n+1]+data[n+2])/3<threshold;},runs=[];
 const scan=(horizontal)=>{const end=horizontal?crop.y+crop.h:crop.x+crop.w,start=horizontal?crop.y:crop.x,lo=horizontal?crop.x:crop.y,hi=horizontal?crop.x+crop.w:crop.y+crop.h;
  for(let a=Math.ceil(start);a<end;a++){let from=-1,last=-1;for(let b=Math.ceil(lo);b<=hi;b++){const dark=b<hi&&black(horizontal?b:a,horizontal?a:b);if(dark){if(from<0)from=b;last=b;}if((!dark&&b-last>2)||b===hi){if(from>=0&&last-from>=minLength)runs.push({axis:horizontal?'h':'v',at:a,start:from,end:last});from=-1;}}}
 };scan(true);scan(false);
 const merged=[];for(const r of runs.sort((a,b)=>a.axis.localeCompare(b.axis)||a.at-b.at||a.start-b.start)){const g=merged.find(m=>m.axis===r.axis&&r.at-m.maxAt<=2&&Math.min(m.end,r.end)-Math.max(m.start,r.start)>.85*Math.min(m.end-m.start,r.end-r.start));if(g){g.maxAt=r.at;g.end=Math.max(g.end,r.end);g.start=Math.min(g.start,r.start);}else merged.push({...r,maxAt:r.at});}
 const suppressed=likelyTreadRuns(merged),candidates=merged.filter((_,i)=>!suppressed.has(i));
 const lines=[];const used=new Set();for(let i=0;i<candidates.length;i++){if(used.has(i))continue;const a=candidates[i];const j=candidates.findIndex((b,n)=>n>i&&!used.has(n)&&b.axis===a.axis&&b.at-a.maxAt>=3&&b.at-a.maxAt<=12&&Math.min(a.end,b.end)-Math.max(a.start,b.start)>.8*Math.min(a.end-a.start,b.end-b.start));if(j>=0){used.add(j);const b=candidates[j];lines.push({axis:a.axis,at:(a.at+b.maxAt)/2,start:Math.max(a.start,b.start),end:Math.min(a.end,b.end),thickness:b.maxAt-a.at,confidence:.7,evidence:'Parallel dark lines; could also be stairs or drawing annotations.'});}else if(a.maxAt-a.at>=2)lines.push({...a,at:(a.at+a.maxAt)/2,thickness:a.maxAt-a.at+1,confidence:.45,evidence:'Thick continuous line; classification unknown.'});}
 const result=lines.slice(0,500);result.suppressedTreadRuns=suppressed.size;return result;
}
export function linesToFloor(lines,{metersPerPixel,origin={x:0,y:0},name='Detected floor'}){if(!Number.isFinite(metersPerPixel)||metersPerPixel<=0||metersPerPixel>.5)throw Error('Calibrate a known distance first.');const walls=lines.filter(l=>(l.end-l.start)*metersPerPixel>=.4).map(l=>{const a=l.axis==='h'?[l.start,l.at,l.end,l.at]:[l.at,l.start,l.at,l.end];return {...wall((a[0]-origin.x)*metersPerPixel,(a[1]-origin.y)*metersPerPixel,(a[2]-origin.x)*metersPerPixel,(a[3]-origin.y)*metersPerPixel),thickness:Math.max(.06,Math.min(.5,l.thickness*metersPerPixel)),classification:'unclassified',locked:true,detection:{confidence:l.confidence,evidence:l.evidence,reviewed:false}};});return {id:uid(),name,elevation:0,rooms:[],walls,items:[],blueprint:null,features:[]};}
export function enclosedRooms(f,{cell=.12,minArea=2}={}){if(!f.walls.length)return[];const xs=f.walls.flatMap(w=>[w.x1,w.x2]),zs=f.walls.flatMap(w=>[w.z1,w.z2]),x=Math.min(...xs)-cell*2,z=Math.min(...zs)-cell*2,w=Math.max(...xs)-x+cell*2,d=Math.max(...zs)-z+cell*2,nx=Math.ceil(w/cell),nz=Math.ceil(d/cell);if(nx*nz>300000)return[];const blocked=new Uint8Array(nx*nz),seen=new Uint8Array(nx*nz);for(let j=0;j<nz;j++)for(let i=0;i<nx;i++){const px=x+(i+.5)*cell,pz=z+(j+.5)*cell;for(const wall of f.walls){const dx=wall.x2-wall.x1,dz=wall.z2-wall.z1,L=dx*dx+dz*dz,t=Math.max(0,Math.min(1,((px-wall.x1)*dx+(pz-wall.z1)*dz)/L));if(Math.hypot(px-wall.x1-t*dx,pz-wall.z1-t*dz)<=wall.thickness/2+cell*.7){blocked[j*nx+i]=1;break;}}}
 const rooms=[];for(let start=0;start<blocked.length;start++){if(blocked[start]||seen[start])continue;const queue=[start];seen[start]=1;let edge=false,ix=nx,iz=nz,ax=0,az=0;for(let n=0;n<queue.length;n++){const q=queue[n],i=q%nx,j=Math.floor(q/nx);edge ||=i===0||j===0||i===nx-1||j===nz-1;ix=Math.min(ix,i);iz=Math.min(iz,j);ax=Math.max(ax,i);az=Math.max(az,j);for(const [di,dj]of [[1,0],[-1,0],[0,1],[0,-1]]){const ni=i+di,nj=j+dj,k=nj*nx+ni;if(ni>=0&&nj>=0&&ni<nx&&nj<nz&&!blocked[k]&&!seen[k]){seen[k]=1;queue.push(k);}}}const rw=(ax-ix+1)*cell,rd=(az-iz+1)*cell;if(!edge&&queue.length*cell*cell>=minArea){const rings=cellRings(queue,nx),outer=rings.sort((a,b)=>Math.abs(signed(b))-Math.abs(signed(a)))[0];if(outer&&outer.length<=2048)rooms.push({id:uid(),name:`Unclassified space ${rooms.length+1}`,x:x+ix*cell,z:z+iz*cell,w:rw,d:rd,points:outer.map(([a,b])=>[(a-ix)*cell,(b-iz)*cell]),holes:rings.slice(1).map(p=>p.map(([a,b])=>[(a-ix)*cell,(b-iz)*cell])),material:'concrete',detection:{confidence:.5,reviewed:false}});}}
 return rooms;
}

const signed=p=>p.reduce((s,a,i)=>{const b=p[(i+1)%p.length];return s+a[0]*b[1]-b[0]*a[1];},0)/2;
function cellRings(cells,nx){const set=new Set(cells),edges=new Map(),add=(a,b)=>{const k=a.join(',');if(!edges.has(k))edges.set(k,[]);edges.get(k).push(b);};for(const q of cells){const i=q%nx,j=Math.floor(q/nx);if(!set.has(q-nx))add([i,j],[i+1,j]);if(!set.has(q+1))add([i+1,j],[i+1,j+1]);if(!set.has(q+nx))add([i+1,j+1],[i,j+1]);if(!set.has(q-1))add([i,j+1],[i,j]);}const rings=[];while(edges.size){const key=edges.keys().next().value,start=key.split(',').map(Number),ring=[start];let current=start;for(let n=0;n<cells.length*4+4;n++){const k=current.join(','),next=edges.get(k)?.pop();if(!edges.get(k)?.length)edges.delete(k);if(!next)break;if(next[0]===start[0]&&next[1]===start[1]){const simple=ring.filter((a,i)=>{const b=ring[(i+ring.length-1)%ring.length],c=ring[(i+1)%ring.length];return (a[0]-b[0])*(c[1]-a[1])!==(a[1]-b[1])*(c[0]-a[0]);});if(simple.length>=3)rings.push(simple);break;}ring.push(next);current=next;}}return rings;}
export function snapWalls(f,tolerance=.05){
 const points=f.walls.flatMap(w=>[{w,x:'x1',z:'z1',ox:w.x1,oz:w.z1},{w,x:'x2',z:'z2',ox:w.x2,oz:w.z2}]),groups=points.map(p=>[p]),changes=[];
 for(let i=0;i<points.length;i++)for(let j=i+1;j<points.length;j++){const a=points[i],b=points[j],ga=groups.find(g=>g.includes(a)),gb=groups.find(g=>g.includes(b));if(ga===gb||ga.some(p=>gb.some(q=>p.w===q.w)))continue;const combined=[...ga,...gb];if(combined.some(p=>combined.some(q=>Math.hypot(p.ox-q.ox,p.oz-q.oz)>tolerance)))continue;const distance=Math.hypot(a.ox-b.ox,a.oz-b.oz);const x=combined.reduce((n,p)=>n+p.ox,0)/combined.length,z=combined.reduce((n,p)=>n+p.oz,0)/combined.length;for(const p of combined){p.w[p.x]=x;p.w[p.z]=z;}groups.splice(groups.indexOf(ga),1);groups.splice(groups.indexOf(gb),1);groups.push(combined);if(distance>1e-8)changes.push({walls:combined.map(p=>p.w.id),distance,reviewed:false});}return changes;
}
export function calibratedScale(metres,pixels){if(!Number.isFinite(metres)||metres<=0||!Number.isFinite(pixels)||pixels<20)throw Error('Confirm a positive measurement and separated scale anchors.');return metres/pixels;}


// Enclosure evidence directly from cropped ink; no semantic room classification is inferred.
export function rasterSpaces({data,width,height},crop,scale,{step=3,minArea=2,rejected=[]}={}){const nx=Math.ceil(crop.w/step),nz=Math.ceil(crop.h/step),blocked=new Uint8Array(nx*nz),seen=new Uint8Array(nx*nz),rooms=[];if(nx*nz>300000)throw Error('Raster crop is too large.');for(let j=0;j<nz;j++)for(let i=0;i<nx;i++){let dark=false;for(let dy=0;dy<step&&!dark;dy++)for(let dx=0;dx<step;dx++){const x=crop.x+i*step+dx,y=crop.y+j*step+dy;if(x>=width||y>=height)continue;const k=(y*width+x)*4;if((data[k]+data[k+1]+data[k+2])/3<150){dark=true;break;}}blocked[j*nx+i]=dark?1:0;}for(let start=0;start<blocked.length;start++){if(blocked[start]||seen[start])continue;const queue=[start];seen[start]=1;let edge=false,ix=nx,iz=nz,ax=0,az=0;for(let n=0;n<queue.length;n++){const q=queue[n],i=q%nx,j=Math.floor(q/nx);edge ||=i===0||j===0||i===nx-1||j===nz-1;ix=Math.min(ix,i);iz=Math.min(iz,j);ax=Math.max(ax,i);az=Math.max(az,j);for(const [di,dj]of [[1,0],[-1,0],[0,1],[0,-1]]){const ni=i+di,nj=j+dj,k=nj*nx+ni;if(ni>=0&&nj>=0&&ni<nx&&nj<nz&&!blocked[k]&&!seen[k]){seen[k]=1;queue.push(k);}}}if(edge||queue.length*(step*scale)**2<minArea)continue;const rings=cellRings(queue,nx).sort((a,b)=>Math.abs(signed(b))-Math.abs(signed(a))),outer=rings[0];if(!outer||outer.length>2048)continue;const local=p=>p.map(([a,b])=>[(a-ix)*step*scale,(b-iz)*step*scale]);const candidate={id:uid(),name:'Unclassified raster space '+(rooms.length+1),x:ix*step*scale,z:iz*step*scale,w:(ax-ix+1)*step*scale,d:(az-iz+1)*step*scale,points:local(outer),holes:rings.slice(1).filter(r=>Math.abs(signed(r))*(step*scale)**2>=.2).slice(0,32).map(local),material:'concrete',detection:{reviewed:false,confidence:.4,evidence:'Enclosed raster ink. Door arcs and annotation lines may affect this boundary; correct against wall geometry.'}};try{validateRoomPolygon(candidate);rooms.push(candidate);}catch(e){rejected.push({boundary:candidate,error:e.message});}}return rooms;}
